def seed_complaint_controls(apps, schema_editor):
    Category = apps.get_model('core', 'ComplaintCategory')
    Alias = apps.get_model('core', 'ComplaintCategoryAlias')
    Control = apps.get_model('core', 'ComplaintCaseControl')
    ParsedMessage = apps.get_model('core', 'ParsedMessage')
    Group = apps.get_model('core', 'GroupSheetConfiguration')
    Location = apps.get_model('core', 'OperationalLocation')
    Customer = apps.get_model('core', 'JawabuCustomer')

    configured_group_ids = []
    for group in Group.objects.all().iterator():
        workflow = group.workflow or {}
        if str(workflow.get('type') or 'case') == 'case':
            configured_group_ids.append(str(group.group_id))
    cases = ParsedMessage.objects.filter(group_id__in=configured_group_ids)

    general, _ = Category.objects.get_or_create(
        key='general-complaint',
        defaults={'label': 'General complaint', 'default_priority': 'normal', 'default_sla_hours': 72},
    )
    categories = {'general complaint': general}
    for label in cases.exclude(complaint_category='').values_list('complaint_category', flat=True).distinct():
        clean_label = ' '.join(str(label or '').split())
        normalized = re.sub(r'[^a-z0-9]+', ' ', clean_label.casefold()).strip()
        if not normalized:
            continue
        key_base = slugify(clean_label)[:70] or 'complaint'
        key = key_base
        suffix = 2
        while Category.objects.filter(key=key).exclude(label__iexact=clean_label).exists():
            key = f'{key_base[:74]}-{suffix}'
            suffix += 1
        category, _ = Category.objects.get_or_create(
            label__iexact=clean_label,
            defaults={'key': key, 'label': clean_label, 'default_priority': 'normal', 'default_sla_hours': 72},
        )
        categories[normalized] = category
        Alias.objects.get_or_create(
            normalized_alias=normalized,
            defaults={'category': category, 'alias': clean_label},
        )

    branches = {
        re.sub(r'[^a-z0-9]+', ' ', str(location.name).casefold()).strip(): location
        for location in Location.objects.filter(location_type='branch')
    }
    for case in cases.iterator():
        normalized_category = re.sub(
            r'[^a-z0-9]+', ' ', str(case.complaint_category or '').casefold(),
        ).strip()
        category = categories.get(normalized_category, general)
        normalized_branch = re.sub(
            r'[^a-z0-9]+', ' ', str(case.branch_region or '').casefold(),
        ).strip()
        branch = branches.get(normalized_branch)

        id_matches = Customer.objects.none()
        phone_matches = Customer.objects.none()
        if str(case.customer_id or '').strip():
            id_matches = Customer.objects.filter(national_id__iexact=str(case.customer_id).strip())
        if str(case.customer_phone or '').strip():
            digits = re.sub(r'\D', '', str(case.customer_phone))
            if digits.startswith('0') and len(digits) == 10:
                digits = '254' + digits[1:]
            elif len(digits) == 9:
                digits = '254' + digits
            phone_matches = Customer.objects.filter(primary_phone=digits)
        id_ids = set(id_matches.values_list('pk', flat=True))
        phone_ids = set(phone_matches.values_list('pk', flat=True))
        customer = None
        match_status = 'unmatched'
        if len(id_ids) == 1 and len(phone_ids) == 1 and id_ids != phone_ids:
            match_status = 'conflict'
        elif len(id_ids) == 1:
            customer = id_matches.first()
            match_status = 'exact_id'
        elif len(phone_ids) == 1:
            customer = phone_matches.first()
            match_status = 'exact_phone'
        elif len(id_ids) > 1 or len(phone_ids) > 1:
            match_status = 'ambiguous'

        started = case.timestamp or case.created_at or django.utils.timezone.now()
        Control.objects.get_or_create(
            parsed_message=case,
            defaults={
                'category': category,
                'branch_ref': branch,
                'customer': customer,
                'customer_match_status': match_status,
                'priority': category.default_priority,
                'sla_target_hours': category.default_sla_hours,
                'sla_started_at': started,
                'sla_due_at': started + timedelta(hours=category.default_sla_hours),
                'sync_status': 'success' if case.synced_to_sheets and not case.last_sync_error else 'pending',
            },
        )


