def seed_complaint_capabilities(apps, schema_editor):
    from core.services.workflow_capabilities import capabilities_for_workflow

    Capability = apps.get_model('core', 'WorkflowRoleCapability')
    for definition in capabilities_for_workflow('complaint_cases'):
        for role in definition.default_roles:
            Capability.objects.get_or_create(
                workflow='complaint_cases', role=role, capability_key=definition.key,
                defaults={'enabled': True, 'effect': 'allow'},
            )


